def get_usuario_externo(apps, relacionamento):
    PrestadorServico = apps.get_model('comum.prestadorservico')
    Vinculo = apps.get_model('comum.vinculo')
    ContentType = apps.get_model('contenttypes.ContentType')
    tipo_relacionamento_prestador = ContentType.objects.get(app_label='comum', model='prestadorservico')
    usuario_externo = PrestadorServico.objects.filter(id=relacionamento.pessoa_fisica_id).first()
    if usuario_externo:
        return usuario_externo
    else:
        pf_dict = relacionamento.pessoa_fisica.__dict__.copy()
        pf_dict.pop('_state')
        pf_dict.pop('id')
        pf_dict.pop('pessoa_ptr_id')
        usuario_externo = PrestadorServico(**pf_dict)
        usuario_externo.cpf = relacionamento.pessoa_fisica.cpf
        usuario_externo.pessoa_fisica_id = relacionamento.pessoa_fisica_id
        usuario_externo.funcionario_ptr_id = relacionamento.pessoa_fisica_id
        usuario_externo.matricula = re.sub(r'\D', '', str(relacionamento.pessoa_fisica.cpf))
        usuario_externo.eh_prestador = True
        usuario_externo.eh_usuario_externo = True
        usuario_externo.ativo = True
        usuario_externo.save()
        Vinculo.objects.create(pessoa=relacionamento.pessoa_fisica, tipo_relacionamento=tipo_relacionamento_prestador, id_relacionamento=usuario_externo.id, secret=usuario_externo.id)
        return usuario_externo


